// APIKey lets a member call the API. It acts as that member, with the member's current role.
//
// Only TokenHash and Last4 are stored. Token is set only on the copy that creates the key, so the caller can show it
// once; it is never stored or saved. (Snapshots from before hashing carry Token, and FromState hashes it on load.)
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
