	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// createdAPIKey is a new API key. It is the only answer that carries the full token, and it is shown once.
type createdAPIKey struct {
	apiKeyView
	Token string `json:"token"`
}

func newAPIKeyView(k store.APIKey) apiKeyView {
	return apiKeyView{ID: k.ID, OrgID: k.OrgID, UserID: k.UserID, Name: k.Name, Last4: k.Last4, CreatedAt: k.CreatedAt,
		LastUsedAt: k.LastUsedAt, RevokedAt: k.RevokedAt}
}

func newCreatedAPIKey(k store.APIKey) createdAPIKey {
	return createdAPIKey{apiKeyView: newAPIKeyView(k), Token: k.Token}
}

