package store

import (
	"encoding/json"
	"strings"
	"testing"
	"time"
)

// validAPIKeyToken reports whether token is "tly_" followed by 40 characters from apiKeyAlphabet.
func validAPIKeyToken(token string) bool {
	body, ok := strings.CutPrefix(token, "tly_")
	if !ok || len(body) != 40 {
		return false
	}
	for _, c := range body {
		if !strings.ContainsRune(apiKeyAlphabet, c) {
			return false
		}
	}
	return true
}

func TestNewAPIKeyToken(t *testing.T) {
	seen := map[string]bool{}
	for range 1000 {
		tok := newAPIKeyToken()
		if !validAPIKeyToken(tok) {
			t.Fatalf("bad token %q", tok)
		}
		if seen[tok] {
			t.Fatalf("token %q repeated", tok)
		}
		seen[tok] = true
	}
}

func TestAPIKeyStoresOnlyTheHash(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, err := s.CreateAPIKey(o.ID, u.ID, "CI", t0)
	if err != nil {
		t.Fatal(err)
	}
	if k.TokenHash != hashToken(k.Token) || k.Last4 != k.Token[len(k.Token)-4:] {
		t.Fatalf("returned key = %+v", k)
	}

	listed := s.APIKeys(o.ID)
	if len(listed) != 1 || listed[0].Token != "" || listed[0].TokenHash != hashToken(k.Token) || listed[0].Last4 != k.Last4 {
		t.Fatalf("listed key = %+v", listed)
	}
	if got, ok := s.APIKey(o.ID, k.ID); !ok || got.Token != "" {
		t.Fatalf("APIKey = %+v %v", got, ok)
	}

	b, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), k.Token) {
		t.Fatal("the snapshot state contains the token")
	}
	if !strings.Contains(string(b), hashToken(k.Token)) {
		t.Fatal("the snapshot state lacks the token's hash")
	}
}

func TestLegacyPlainTokenIsHashedOnLoad(t *testing.T) {
	const token = "tly_00000000000000000000000000000003"
	st := State{APIKeys: []APIKey{{ID: "key_000001", OrgID: "org_000001", UserID: "usr_000002", Name: "old", Token: token, CreatedAt: t0}}}
	s, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := s.APIKeyByToken(token); !ok || got.ID != "key_000001" {
		t.Fatalf("the legacy key does not work: %+v %v", got, ok)
	}
	out := s.Export()
	if len(out.APIKeys) != 1 || out.APIKeys[0].Token != "" || out.APIKeys[0].TokenHash != hashToken(token) || out.APIKeys[0].Last4 != "0003" {
		t.Fatalf("exported key = %+v", out.APIKeys)
	}
	b, _ := json.Marshal(out)
	if strings.Contains(string(b), token) {
		t.Fatal("the next snapshot contains the legacy token")
	}
}

func TestTouchAPIKeyRecordsUseAtMostOncePerMinute(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "CI", t0)
	lastUsed := func() time.Time {
		t.Helper()
		got, _ := s.APIKey(o.ID, k.ID)
		if got.LastUsedAt == nil {
			t.Fatal("LastUsedAt is nil")
		}
		return *got.LastUsedAt
	}

	s.TouchAPIKey(k.ID, t0)
	if !lastUsed().Equal(t0) {
		t.Fatalf("first use = %v", lastUsed())
	}
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if !lastUsed().Equal(t0) {
		t.Fatalf("a use 59s later changed LastUsedAt to %v", lastUsed())
	}
	s.TouchAPIKey(k.ID, t0.Add(60*time.Second))
	if !lastUsed().Equal(t0.Add(60 * time.Second)) {
		t.Fatalf("a use 60s later left LastUsedAt at %v", lastUsed())
	}
}

