import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
)

func TestAPIKeyAnswersShowTheTokenOnlyWhenCreated(t *testing.T) {
	e := apitest.New(t)
	r := e.Do("POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"})
	if r.Code != http.StatusCreated {
		t.Fatalf("create: %s", r)
	}
	var created map[string]any
	if err := json.Unmarshal(r.Body.Bytes(), &created); err != nil {
		t.Fatal(err)
	}
	token, _ := created["token"].(string)
	if !strings.HasPrefix(token, "tly_") || len(token) != len("tly_")+40 {
		t.Fatalf("created token = %q", token)
	}
	if created["last4"] != token[len(token)-4:] {
		t.Fatalf("last4 = %v, want %q", created["last4"], token[len(token)-4:])
	}
	if _, ok := created["token_hash"]; ok {
		t.Fatalf("create answer has a token hash: %s", r)
	}

	r = e.Do("GET", "/v1/api-keys", e.Acme.Key, nil)
	if r.Code != http.StatusOK {
		t.Fatalf("list: %s", r)
	}
	body := r.Body.String()
	if strings.Contains(body, token) || strings.Contains(body, "token") {
		t.Fatalf("list shows a token or hash: %s", body)
	}
	var keys struct{ Items []map[string]any }
	if err := json.Unmarshal(r.Body.Bytes(), &keys); err != nil {
		t.Fatal(err)
	}
	found := false
	for _, k := range keys.Items {
		if k["id"] == created["id"] {
			found = true
			if k["last4"] != created["last4"] || k["name"] != "CI" || k["user_id"] == nil || k["created_at"] == nil {
				t.Fatalf("listed key = %v", k)
			}
		}
	}
	if !found {
		t.Fatalf("the new key is not listed: %s", body)
	}

	e.MustDo(http.StatusOK, "GET", "/v1/org", token, nil, nil)
}

